arguments.command:
cd /tmp/sv-4c69b1c1c52a41feab3905fa32d6de48 && \
# Look for ALL symbols covering the range around 0x2f4b20 and 0x2f4c84 in debug file
aarch64-linux-gnu-readelf -sW mono.debug 2>/dev/null | awk '
$4 == "FUNC" || $4 == "OBJECT" || $4 == "NOTYPE" {
  val=strtonum("0x"$2); size=strtonum($3);
  if (val >= 0x2f4000 && val <= 0x2f5000) print
}' | head -20
echo "==="
# Also check if these could be sgen-related symbols
aarch64-linux-gnu-readelf -sW mono.debug 2>/dev/null | grep -i "sgen.*worker\|worker.*sgen\|sgen_workers" | head -10

